create type gov_repo.dora_incident_category as enum ('cyber_attack','ransomware','data_breach','system_failure','software_defect','third_party_failure','ai_system_failure','process_failure','natural_disaster','supply_chain_attack','insider_threat','ddos','social_engineering','other');
create type gov_repo.dora_reporting_phase as enum ('not_required','initial_notification','intermediate_report','final_report','voluntary_notification','all_complete');
create type gov_repo.ict_function_type as enum ('critical','important','standard','regulatory_reporting','customer_facing','payment_settlement','risk_management','internal_operations');
create type gov_repo.rca_method as enum ('five_whys','fishbone_ishikawa','fault_tree_analysis','event_timeline','bow_tie','failure_mode_effects','kill_chain','blameless_postmortem','combined');
create type gov_repo.recovery_status as enum ('not_started','containment_active','eradication_active','recovery_active','restored_partial','restored_full','monitoring_period','lessons_learned_pending','closed');
do $$ begin if not exists(select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='system_status') then create type gov_repo.system_status as enum ('development','testing','production','decommissioned'); end if; end $$;
do $$ begin if not exists(select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='dora_criticality') then create type gov_repo.dora_criticality as enum ('critical','high','medium','low'); end if; end $$;
do $$ begin if not exists(select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='gov_repo' and t.typname='incident_severity') then create type gov_repo.incident_severity as enum ('critical','high','medium','low'); end if; end $$;;
